    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
    transform: translateY(-2px);
  }
  
  /* Smooth icon animation */
  .stat-card i {
    transition: transform 0.3s ease-in-out;
  }
  
  .stat-card:hover i {
    transform: scale(1.1);
  }
  
